using System.Collections.Frozen;

namespace MatterFlow.IntegrationTests.Security;

/// <summary>How an endpoint relates to the sensitive-matter rule (README 12.2).</summary>
public enum AccessKind
{
    /// <summary>A resource by id: a hidden one answers 404, byte for byte like a missing id.</summary>
    Gated,

    /// <summary>A list: no hidden row, no hidden id, no sentinel.</summary>
    List,

    /// <summary>A number or a derived collection (counts, boards, facets): computed from visible rows only.</summary>
    Aggregate,

    /// <summary>A write: a hidden target answers 404 and changes nothing (walked by the feature suites named in the README inventory).</summary>
    Write,

    /// <summary>No matter data; the reason says why.</summary>
    Neutral,

    /// <summary>Not decided in epic #788: Reports (README section 15, issue #808).</summary>
    Open,
}

/// <summary>The kind of record an id in the route points at.</summary>
public enum IdKind
{
    None,
    Task,
    Matter,
    Project,
    Asset,
    Notification,

    /// <summary>An asset reached through its matter only (the My Matters page): visible exactly when its matter is, not through a task assigned to the viewer.</summary>
    MatterAsset,
}

/// <summary>One classified endpoint operation. <paramref name="Calls"/> are the requests the persona walk sends (placeholders <c>{matter}</c>, <c>{task}</c>, <c>{project}</c>, <c>{asset}</c>, <c>{client}</c>, <c>{user}</c> expand to the universe ids).</summary>
public sealed record AccessEntry(AccessKind Kind, IdKind Id, string Reason, string[] Calls);

